import{_ as r,c as l,o as i,a2 as a}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"自訂設定","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/customize.md","filePath":"zh-TW/guide/customize.md","lastUpdated":1793163976000}'),o={name:"zh-TW/guide/customize.md"};function n(e,t,s,d,g,h){return i(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="自訂設定" tabindex="-1">自訂設定 <a class="header-anchor" href="#自訂設定" aria-label="Permalink to &quot;自訂設定&quot;">​</a></h1><p>透過自訂您的壓縮檔管理體驗，讓 NueZip 真正屬於您。本指南涵蓋所有可個人化的項目。</p><h2 id="一般偏好" tabindex="-1">一般偏好 <a class="header-anchor" href="#一般偏好" aria-label="Permalink to &quot;一般偏好&quot;">​</a></h2><p>開啟 <strong>NueZip → 設定</strong>（或按下 <code>Cmd+,</code>）以存取所有自訂選項。</p><h3 id="外觀" tabindex="-1">外觀 <a class="header-anchor" href="#外觀" aria-label="Permalink to &quot;外觀&quot;">​</a></h3><ul><li><strong>主題</strong>：在淺色、深色或系統（跟隨 macOS 外觀）之間選擇</li><li><strong>圖示樣式</strong>：設定為單色或彩色選單列圖示</li><li><strong>語言</strong>：從支援的語言中選擇（English、中文、日本語、한국어 等）</li></ul><h2 id="壓縮預設值" tabindex="-1">壓縮預設值 <a class="header-anchor" href="#壓縮預設值" aria-label="Permalink to &quot;壓縮預設值&quot;">​</a></h2><p>設定您偏好的壓縮預設值：</p><table tabindex="0"><thead><tr><th>設定</th><th>選項</th><th>說明</th></tr></thead><tbody><tr><td><strong>預設格式</strong></td><td>ZIP、7z、TAR、GZIP、BZIP2、XZ</td><td>快速壓縮所用的壓縮檔格式</td></tr><tr><td><strong>壓縮層級</strong></td><td>Store、Fast、Normal、Maximum、Ultra</td><td>速度與壓縮比之間的取捨</td></tr><tr><td><strong>加密</strong></td><td>None、AES-128、AES-256</td><td>ZIP/7z 壓縮檔的預設加密</td></tr><tr><td><strong>卷大小</strong></td><td>自訂（MB）</td><td>多分割卷壓縮檔的預設分割大小</td></tr></tbody></table><h3 id="設定範例" tabindex="-1">設定範例 <a class="header-anchor" href="#設定範例" aria-label="Permalink to &quot;設定範例&quot;">​</a></h3><p>針對日常使用：</p><ul><li><strong>格式</strong>：ZIP</li><li><strong>層級</strong>：Normal</li><li><strong>加密</strong>：AES-256（針對敏感檔案）</li><li><strong>卷</strong>：關閉</li></ul><p>針對封存：</p><ul><li><strong>格式</strong>：7-Zip</li><li><strong>層級</strong>：Ultra</li><li><strong>加密</strong>：AES-256</li><li><strong>卷</strong>：4.7 GB（以符合 DVD 容量）</li></ul><h2 id="解壓縮偏好" tabindex="-1">解壓縮偏好 <a class="header-anchor" href="#解壓縮偏好" aria-label="Permalink to &quot;解壓縮偏好&quot;">​</a></h2><p>自訂解壓縮行為：</p><ul><li><strong>預設解壓縮到子資料夾</strong>：解壓縮時自動建立具名資料夾</li><li><strong>解壓縮後開啟資料夾</strong>：在 Finder 中顯示解壓縮出的內容</li><li><strong>覆寫行為</strong>：詢問、一律覆寫，或跳過現有檔案</li><li><strong>保留檔案日期</strong>：保留壓縮檔中的原始時間戳記</li></ul><h2 id="finder-擴充功能" tabindex="-1">Finder 擴充功能 <a class="header-anchor" href="#finder-擴充功能" aria-label="Permalink to &quot;Finder 擴充功能&quot;">​</a></h2><p>管理 Finder 右鍵選單整合：</p><ul><li><strong>啟用/停用</strong>：開啟或關閉右鍵選單項目</li><li><strong>快速動作</strong>：選擇哪些動作出現在右鍵選單中 <ul><li>在此解壓縮</li><li>解壓縮到資料夾</li><li>壓縮為 ZIP</li><li>使用選項壓縮</li></ul></li></ul><p>請在以下位置管理：<strong>系統設定 → 隱私權與安全性 → 擴充功能 → Finder 擴充功能</strong></p><h2 id="選單列-匣子-圖示" tabindex="-1">選單列（匣子）圖示 <a class="header-anchor" href="#選單列-匣子-圖示" aria-label="Permalink to &quot;選單列（匣子）圖示&quot;">​</a></h2><p>自訂選單列拖放面板：</p><ul><li><strong>顯示於選單列</strong>：啟用/停用匣子圖示</li><li><strong>自動關閉面板</strong>：解壓縮後關閉拖放面板</li><li><strong>最近壓縮檔</strong>：顯示的最近項目數量</li><li><strong>關閉時退出</strong>：App 是否留在背景執行</li></ul><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><ul><li><strong>顯示完成提醒</strong>：長時間操作完成時發出通知</li><li><strong>顯示錯誤提醒</strong>：對失敗的操作顯示通知</li><li><strong>音效</strong>：操作完成時播放音效</li></ul><h2 id="一般設定" tabindex="-1">一般設定 <a class="header-anchor" href="#一般設定" aria-label="Permalink to &quot;一般設定&quot;">​</a></h2><p>請在 <strong>設定 → 一般</strong> 中存取這些項目：</p><ul><li><strong>語言</strong>：在 English、中文、日本語 等之間切換</li><li><strong>登入時啟動</strong>：登入時 NueZip 自動啟動</li><li><strong>主題</strong>：淺色或深色模式（預設跟隨系統）</li><li><strong>選單列圖示</strong>：顯示或隱藏選單列圖示</li></ul><h2 id="小訣竅" tabindex="-1">小訣竅 <a class="header-anchor" href="#小訣竅" aria-label="Permalink to &quot;小訣竅&quot;">​</a></h2><ul><li>一次設定好您喜愛的壓縮預設值，加快日常封存速度</li><li>啟用「登入時啟動」，讓 NueZip 永遠只需一鍵即可使用</li><li>使用 Finder 擴充功能以獲得最快的解壓縮/壓縮工作流程</li><li>定期在系統設定中檢視資料夾存取權，保持整潔</li></ul>',31)])])}const p=r(o,[["render",n]]);export{c as __pageData,p as default};
